parameters.query:
SELECT front_matter
FROM publishing_progress
WHERE manuscript_id = '{{ $("Set Initial Variables").item.json.manuscriptId }}';

SELECT back_matter
FROM publishing_progress
WHERE manuscript_id = '{{ $("Set Initial Variables").item.json.manuscriptId }}';

