// Get all the data from previous nodes
const chapters = $("Load All Chapters").all();
const frontMatterData = $("Load Front Matter").first().json;
const backMatterData = $("Load Back Matter").first().json;
const metadataRaw = $("Load Manuscript Metadata").first().json;
const settings = $("Set Initial Variables").first().json;

// Parse front and back matter (they come as JSONB from Postgres)
const frontMatter = frontMatterData.front_matter || {};
const backMatter = backMatterData.back_matter || {};

// Format author name from Postgres results
const authorName = metadataRaw.first_name + " " + metadataRaw.last_name;
const bookTitle = metadataRaw.title;

// Build HTML structure
let html = "<!DOCTYPE html>\n";
html += '<html lang="en">\n';
html += "<head>\n";
html += '  <meta charset="UTF-8">\n';
html += "  <title>" + bookTitle + "</title>\n";
html += "  <style>\n";
html += "    body {\n";
html += "      font-family: '" + settings.fontFamily + "', serif;\n";
html += "      font-size: " + settings.fontSize + "pt;\n";
html += "      line-height: " + settings.lineSpacing + ";\n";
html +=
  "      margin: " +
  settings.margins.top +
  "in " +
  settings.margins.outer +
  "in " +
  settings.margins.bottom +
  "in " +
  settings.margins.inner +
  "in;\n";
html += "    }\n";
html += "    h1.book-title {\n";
html += "      text-align: center;\n";
html += "      font-size: 32pt;\n";
html += "      margin-top: 3in;\n";
html += "      margin-bottom: 0.5in;\n";
html += "      page-break-before: always;\n";
html += "    }\n";
html += "    h2.chapter-title {\n";
html += "      text-align: " + settings.chapterStyle + ";\n";
html += "      font-size: 18pt;\n";
html += "      margin-top: 2in;\n";
html += "      margin-bottom: 1in;\n";
html += "      page-break-before: always;\n";
html += "    }\n";
html += "    p {\n";
html += "      text-indent: 0.5in;\n";
html += "      margin: 0;\n";
html += "      text-align: justify;\n";
html += "    }\n";
html += "    p.first-paragraph {\n";
html += "      text-indent: 0;\n";
html += "    }\n";
html += "    p.scene-break {\n";
html += "      text-align: center;\n";
html += "      text-indent: 0;\n";
html += "      margin: 1em 0;\n";
html += "    }\n";
html += "    .copyright-page {\n";
html += "      page-break-before: always;\n";
html += "      font-size: 10pt;\n";
html += "      text-align: left;\n";
html += "    }\n";
html += "    .dedication {\n";
html += "      page-break-before: always;\n";
html += "      text-align: center;\n";
html += "      font-style: italic;\n";
html += "      margin-top: 3in;\n";
html += "    }\n";
html += "    .author-bio {\n";
html += "      page-break-before: always;\n";
html += "      margin-top: 1in;\n";
html += "    }\n";
html += "    @page {\n";
html +=
  "      margin: " +
  settings.margins.top +
  "in " +
  settings.margins.outer +
  "in " +
  settings.margins.bottom +
  "in " +
  settings.margins.inner +
  "in;\n";
html += "    }\n";
html += "  </style>\n";
html += "</head>\n";
html += "<body>\n";

// FRONT MATTER - Title Page
if (frontMatter.title_page) {
  html += '<div class="title-page">\n';
  html +=
    '  <h1 class="book-title">' +
    (frontMatter.title_page.title || bookTitle) +
    "</h1>\n";

  if (frontMatter.title_page.subtitle) {
    html +=
      '  <p style="text-align:center; font-size:18pt; margin-top:0.5in;">' +
      frontMatter.title_page.subtitle +
      "</p>\n";
  }

  html +=
    '  <p style="text-align:center; margin-top:2in; font-size:14pt;">' +
    (frontMatter.title_page.author || authorName) +
    "</p>\n";
  html += "</div>\n";
}

// FRONT MATTER - Copyright Page
if (frontMatter.copyright_page) {
  html += '<div class="copyright-page">\n';
  html +=
    "  <p>Copyright © " +
    (frontMatter.copyright_page.copyright_year || new Date().getFullYear()) +
    " " +
    (frontMatter.title_page?.author || authorName) +
    "</p>\n";

  if (frontMatter.copyright_page.publisher) {
    html +=
      "  <p>Published by " + frontMatter.copyright_page.publisher + "</p>\n";
  }

  if (frontMatter.copyright_page.isbn) {
    html += "  <p>ISBN: " + frontMatter.copyright_page.isbn + "</p>\n";
  }

  html += "  <br><br>\n";
  html +=
    "  <p>" + (frontMatter.copyright_page.copyright_notice || "") + "</p>\n";
  html += "  <br>\n";
  html += "  <p>" + (frontMatter.copyright_page.disclaimer || "") + "</p>\n";
  html += "</div>\n";
}

// FRONT MATTER - Dedication
if (frontMatter.dedication && frontMatter.dedication.text) {
  html += '<div class="dedication">\n';
  html += "  <p>" + frontMatter.dedication.text + "</p>\n";
  html += "</div>\n";
}

// FRONT MATTER - Acknowledgements
if (frontMatter.acknowledgements && frontMatter.acknowledgements.text) {
  const ackText = frontMatter.acknowledgements.text.replace(/\n\n/g, "</p><p>");
  html += '<div style="page-break-before: always;">\n';
  html += '  <h2 style="text-align: center;">Acknowledgements</h2>\n';
  html += '  <p class="first-paragraph">' + ackText + "</p>\n";
  html += "</div>\n";
}

// FRONT MATTER - Epigraph
if (frontMatter.epigraph && frontMatter.epigraph.quote) {
  html +=
    '<div style="page-break-before: always; text-align: center; margin-top: 3in; font-style: italic;">\n';
  html += '  <p>"' + frontMatter.epigraph.quote + '"</p>\n';
  html +=
    '  <p style="margin-top: 1em;">— ' +
    frontMatter.epigraph.attribution +
    "</p>\n";
  html += "</div>\n";
}

// FRONT MATTER - Preface
if (frontMatter.preface && frontMatter.preface.text) {
  const prefaceText = frontMatter.preface.text.replace(/\n\n/g, "</p><p>");
  html += '<div style="page-break-before: always;">\n';
  html += '  <h2 style="text-align: center;">Preface</h2>\n';
  html += '  <p class="first-paragraph">' + prefaceText + "</p>\n";
  html += "</div>\n";
}

// MAIN CONTENT - Chapters
chapters.forEach(function (chapter) {
  const chapterData = chapter.json;

  // Detect prologue/epilogue by chapter number
  const isPrologue = chapterData.chapter_number === 0;
  const isEpilogue = chapterData.chapter_number === 999;

  // Build chapter title
  let chapterTitle = "";
  if (isPrologue) {
    chapterTitle = "Prologue";
  } else if (isEpilogue) {
    chapterTitle = "Epilogue";
  } else {
    chapterTitle = "Chapter " + chapterData.chapter_number;
    if (chapterData.title) {
      chapterTitle +=
        '<br><span style="font-size:14pt; font-weight:normal;">' +
        chapterData.title +
        "</span>";
    }
  }

  html += '<h2 class="chapter-title">' + chapterTitle + "</h2>\n";

  // Process chapter content
  if (chapterData.content) {
    const paragraphs = chapterData.content.split("\n\n");

    paragraphs.forEach(function (para, pIndex) {
      para = para.trim();
      if (!para) return;

      // Check if it's a scene break
      if (para === "***" || para === "* * *" || para === settings.sceneBreak) {
        html += '<p class="scene-break">' + settings.sceneBreak + "</p>\n";
      } else {
        const isFirstPara = pIndex === 0;
        html +=
          "<p" +
          (isFirstPara ? ' class="first-paragraph"' : "") +
          ">" +
          para +
          "</p>\n";
      }
    });
  }
});

// BACK MATTER - Author Bio
if (backMatter.author_bio && backMatter.author_bio.bio_text) {
  html += '<div class="author-bio">\n';
  html += '  <h2 style="text-align: center;">About the Author</h2>\n';

  if (backMatter.author_bio.author_tagline) {
    html +=
      '  <p style="text-align: center; font-style: italic; margin-bottom: 1em;">' +
      backMatter.author_bio.author_tagline +
      "</p>\n";
  }

  const bioText = backMatter.author_bio.bio_text.replace(/\n\n/g, "</p><p>");
  html += '  <p class="first-paragraph">' + bioText + "</p>\n";
  html += "</div>\n";
}

// BACK MATTER - Author Note
if (backMatter.author_note && backMatter.author_note.text) {
  const noteText = backMatter.author_note.text.replace(/\n\n/g, "</p><p>");
  html += '<div style="page-break-before: always;">\n';
  html += '  <h2 style="text-align: center;">A Note from the Author</h2>\n';
  html += '  <p class="first-paragraph">' + noteText + "</p>\n";
  html += "</div>\n";
}

// BACK MATTER - Next Book Preview
if (
  backMatter.next_book_preview &&
  backMatter.next_book_preview.title &&
  backMatter.next_book_preview.preview_text
) {
  const previewText = backMatter.next_book_preview.preview_text.replace(
    /\n\n/g,
    "</p><p>",
  );
  html += '<div style="page-break-before: always;">\n';
  html += '  <h2 style="text-align: center;">Coming Soon</h2>\n';
  html +=
    '  <h3 style="text-align: center; font-size: 16pt; font-weight: normal; margin-bottom: 1in;">' +
    backMatter.next_book_preview.title +
    "</h3>\n";
  html += '  <p class="first-paragraph">' + previewText + "</p>\n";
  html += "</div>\n";
}

// Close HTML
html += "</body>\n";
html += "</html>";

// Return the complete HTML and metadata
return [
  {
    json: {
      html: html,
      manuscriptId: settings.manuscriptId,
      title: bookTitle,
      author: frontMatter.title_page?.author || authorName,
      formats: settings.formats,
      settings: settings,
    },
  },
];

